+	plan, err := fixture.task.AdmittedPlan()
+	if err != nil || plan == nil {
+		t.Fatalf("admitted plan = %#v, %v", plan, err)
+	}
+	before := plan.SHA256()
+	if relaunchNeedsPlanRevision(plan, plan.Launch.ProfileName) {
